/**
 * CampusLoop Main Application Controller
 * Mounts components, coordinates reactive rendering, event delegation, and top-layer dialogs
 */

import './styles/main.css';
import { store } from './state/store.js';
import { renderHeader } from './components/Header.js';
import { renderMarketplaceView } from './components/MarketplaceView.js';
import { renderProfileView } from './components/ProfileView.js';
import { renderPerksView } from './components/PerksView.js';
import { renderFooter } from './components/Footer.js';
import { renderItemDetailModal } from './components/ItemDetailModal.js';
import { renderCheckoutModal } from './components/CheckoutModal.js';
import { renderOrderSuccessModal } from './components/OrderSuccessModal.js';
import { renderListItemModal } from './components/ListItemModal.js';
import { renderChatModal } from './components/ChatModal.js';
import { renderLoginModal } from './components/LoginModal.js';
import { renderIcon } from './data/icons.js';

class App {
  constructor() {
    this.appRoot = document.getElementById('app');
    this.modalRoot = document.getElementById('modal-root');
    this.toastRoot = document.getElementById('toast-root');
    
    // In-memory modal form state
    this.modalState = {
      checkoutDays: 1,
      checkoutUseCoins: false,
      listFormData: { type: 'rent' }
    };

    this.init();
  }

  init() {
    // Subscribe to store updates
    store.subscribe(() => {
      this.applyTheme();
      this.render();
    });

    // Initialize theme
    this.applyTheme();

    // Attach global event listeners
    this.attachEventListeners();

    // Initial render
    this.render();
  }

  applyTheme() {
    const state = store.getState();
    const theme = state.theme;
    const root = document.documentElement;

    if (theme === 'dark') {
      root.setAttribute('data-theme', 'dark');
    } else if (theme === 'light') {
      root.setAttribute('data-theme', 'light');
    } else {
      // System preference
      const prefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
      root.setAttribute('data-theme', prefersDark ? 'dark' : 'light');
    }
  }

  render() {
    const state = store.getState();
    const activeView = state.ui.view;

    // 1. Render Main View
    let viewContent = '';
    if (activeView === 'profile') {
      viewContent = renderProfileView(state);
    } else if (activeView === 'perks') {
      viewContent = renderPerksView(state);
    } else {
      viewContent = renderMarketplaceView(state);
    }

    this.appRoot.innerHTML = `
      ${renderHeader(state)}
      ${viewContent}
      ${renderFooter()}
    `;

    // 2. Render Modal Overlay
    this.renderModal(state);

    // 3. Render Toasts
    this.renderToasts(state);
  }

  renderModal(state) {
    const activeModal = state.ui.activeModal;
    if (!activeModal) {
      this.modalRoot.innerHTML = '';
      return;
    }

    let modalContent = '';
    const { name, data } = activeModal;

    switch (name) {
      case 'itemDetail': {
        const item = state.items.find(i => i.id === data.id);
        modalContent = renderItemDetailModal(item);
        break;
      }
      case 'checkout': {
        const item = state.items.find(i => i.id === data.id);
        modalContent = renderCheckoutModal(item, this.modalState.checkoutDays, this.modalState.checkoutUseCoins);
        break;
      }
      case 'orderSuccess': {
        modalContent = renderOrderSuccessModal(data.order, data.item);
        break;
      }
      case 'list': {
        modalContent = renderListItemModal(this.modalState.listFormData);
        break;
      }
      case 'chat': {
        modalContent = renderChatModal(data.orderId);
        break;
      }
      case 'login': {
        modalContent = renderLoginModal(data);
        break;
      }
      default:
        modalContent = '';
    }

    if (modalContent) {
      this.modalRoot.innerHTML = `
        <div class="modal-overlay" data-action="overlay-click">
          ${modalContent}
        </div>
      `;

      // Auto-scroll chat history if opened
      const chatHistory = document.getElementById('chat-history');
      if (chatHistory) {
        chatHistory.scrollTop = chatHistory.scrollHeight;
      }
    } else {
      this.modalRoot.innerHTML = '';
    }
  }

  renderToasts(state) {
    const toasts = state.ui.toasts;
    if (!toasts.length) {
      this.toastRoot.innerHTML = '';
      return;
    }

    this.toastRoot.innerHTML = `
      <div class="toast-stack">
        ${toasts.map(t => `
          <div class="toast-item ${t.type}" role="status">
            <span>${t.message}</span>
          </div>
        `).join('')}
      </div>
    `;
  }

  attachEventListeners() {
    // Click delegation
    document.addEventListener('click', (e) => {
      const target = e.target.closest('[data-action]');
      if (!target) return;

      const action = target.getAttribute('data-action');
      this.handleAction(action, target, e);
    });

    // Form submission delegation
    document.addEventListener('submit', (e) => {
      this.handleFormSubmit(e);
    });

    // Input & Change delegation (live filters, sliders, etc.)
    document.addEventListener('input', (e) => {
      if (e.target.id === 'search-input') {
        store.setSearch(e.target.value);
      } else if (e.target.id === 'co-days-input') {
        const days = parseInt(e.target.value, 10) || 1;
        this.modalState.checkoutDays = days;
        // Re-render modal smoothly
        this.renderModal(store.getState());
      }
    });

    document.addEventListener('change', (e) => {
      if (e.target.id === 'sort-select') {
        store.setSort(e.target.value);
      } else if (e.target.id === 'co-use-coins') {
        this.modalState.checkoutUseCoins = e.target.checked;
        this.renderModal(store.getState());
      }
    });

    // Keyboard support: Escape closes active modal
    document.addEventListener('keydown', (e) => {
      if (e.key === 'Escape' && store.getState().ui.activeModal) {
        store.closeModal();
      }
    });
  }

  handleAction(action, target, event) {
    switch (action) {
      // Demo Personas
      case 'switch-user': {
        const userId = target.getAttribute('data-user');
        store.switchUser(userId);
        break;
      }
      case 'fast-login': {
        const userId = target.getAttribute('data-user');
        store.switchUser(userId);
        store.closeModal();
        break;
      }

      // Navigation
      case 'nav': {
        const view = target.getAttribute('data-view');
        store.setView(view);
        window.scrollTo({ top: 0, behavior: 'smooth' });
        break;
      }
      case 'set-profile-tab': {
        const tab = target.getAttribute('data-tab');
        store.setProfileTab(tab);
        break;
      }

      // Theme
      case 'toggle-theme': {
        store.toggleTheme();
        break;
      }

      // Filtering & Search
      case 'set-category': {
        const cat = target.getAttribute('data-cat');
        store.setCategory(cat);
        break;
      }
      case 'set-type': {
        const type = target.getAttribute('data-type');
        store.setType(type);
        break;
      }
      case 'clear-search': {
        store.setSearch('');
        break;
      }
      case 'reset-filters': {
        store.setSearch('');
        store.setCategory('all');
        store.setType('all');
        break;
      }

      // Modals Open / Close
      case 'open-detail-modal': {
        const id = parseInt(target.getAttribute('data-id'), 10);
        store.openModal('itemDetail', { id });
        break;
      }
      case 'open-checkout-modal': {
        const id = parseInt(target.getAttribute('data-id'), 10);
        this.modalState.checkoutDays = 1;
        this.modalState.checkoutUseCoins = false;
        store.openModal('checkout', { id });
        break;
      }
      case 'open-list-modal': {
        this.modalState.listFormData = { type: 'rent' };
        store.openModal('list');
        break;
      }
      case 'open-login-modal': {
        store.openModal('login');
        break;
      }
      case 'open-chat-modal': {
        const orderId = target.getAttribute('data-order-id');
        store.openModal('chat', { orderId });
        break;
      }
      case 'close-modal': {
        store.closeModal();
        break;
      }
      case 'overlay-click': {
        if (event.target === target) {
          store.closeModal();
        }
        break;
      }

      // List Item Form Sub-actions
      case 'form-set-type': {
        const type = target.getAttribute('data-type');
        this.modalState.listFormData.type = type;
        this.renderModal(store.getState());
        break;
      }

      // Marketplace & Orders
      case 'return-rental': {
        const orderId = target.getAttribute('data-order-id');
        store.updateRentalStatus(orderId, 'completed');
        break;
      }
      case 'withdraw-listing': {
        const itemId = parseInt(target.getAttribute('data-id'), 10);
        store.withdrawListing(itemId);
        break;
      }
      case 'approve-listing': {
        const itemId = parseInt(target.getAttribute('data-id'), 10);
        store.approveListing(itemId);
        break;
      }
      case 'reject-listing': {
        const itemId = parseInt(target.getAttribute('data-id'), 10);
        store.rejectListing(itemId, 'Did not meet safety guidelines');
        break;
      }

      // Perks
      case 'redeem-perk': {
        const perkId = target.getAttribute('data-perk-id');
        store.redeemPerk(perkId);
        break;
      }

      // Quick Chat Replies
      case 'quick-reply': {
        const text = target.getAttribute('data-text');
        const input = document.getElementById('chat-input');
        if (input) {
          input.value = text;
          input.focus();
        }
        break;
      }
    }
  }

  handleFormSubmit(e) {
    e.preventDefault();
    const form = e.target;

    // Checkout Form
    if (form.id === 'checkout-form') {
      const itemId = parseInt(form.getAttribute('data-item-id'), 10);
      const item = store.getState().items.find(i => i.id === itemId);
      if (!item) return;

      store.checkout(item, {
        days: this.modalState.checkoutDays,
        useCoins: this.modalState.checkoutUseCoins
      });
    }

    // List Item Form
    else if (form.id === 'list-item-form') {
      const title = document.getElementById('item-title').value.trim();
      const cat = document.getElementById('item-category').value;
      const condition = document.getElementById('item-condition').value;
      const price = parseFloat(document.getElementById('item-price').value);
      const deposit = parseFloat(document.getElementById('item-deposit').value) || 0;
      const location = document.getElementById('item-location').value;
      const desc = document.getElementById('item-desc').value.trim();
      const type = this.modalState.listFormData.type || 'rent';

      const errorBox = document.getElementById('list-form-error');
      if (!title || !desc || !(price > 0)) {
        if (errorBox) {
          errorBox.textContent = 'Please fill out all required fields with a valid price.';
          errorBox.style.display = 'block';
        }
        return;
      }

      // Assign semantic icon based on category
      const iconMap = {
        Mobility: 'bike',
        Study: 'book',
        Creative: 'camera',
        Home: 'chair',
        Tech: 'laptop'
      };

      store.listItem({
        title,
        desc,
        details: desc,
        cat,
        condition,
        price,
        deposit,
        location,
        type,
        icon: iconMap[cat] || 'box'
      });
    }

    // Chat Message Form
    else if (form.id === 'chat-send-form') {
      const orderId = form.getAttribute('data-order-id');
      const input = document.getElementById('chat-input');
      const text = input ? input.value : '';

      if (text.trim()) {
        store.sendChatMessage(orderId, text);
        if (input) input.value = '';
        const chatHistory = document.getElementById('chat-history');
        if (chatHistory) {
          chatHistory.scrollTop = chatHistory.scrollHeight;
        }
      }
    }

    // Login Form
    else if (form.id === 'email-login-form') {
      const email = document.getElementById('login-email').value;
      const password = document.getElementById('login-password').value;
      const result = store.login(email, password);

      if (!result.success) {
        const errorBox = document.getElementById('login-error');
        if (errorBox) {
          errorBox.textContent = result.message;
          errorBox.style.display = 'block';
        }
      }
    }
  }
}

// Bootstrap app on DOM ready
document.addEventListener('DOMContentLoaded', () => {
  new App();
});
