export function renderIcon(name, className = '', viewBox = '0 0 24 24') {
  const svgContent = ICONS[name] || ICONS.mark;
  // If it's a large illustration
  if (['bike','calc','camera','chair','coat','book','laptop','mic','scooter','fridge','cpu'].includes(name)) {
    return `<svg class="${className}" viewBox="0 0 96 96" fill="none" stroke="currentColor" stroke-width="4.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${svgContent}</svg>`;
  }
  return `<svg class="${className}" viewBox="${viewBox}" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${svgContent}</svg>`;
}
